-- Support Ticket SLA — analysis queries (SQLite, run against outputs/tickets.db)
-- Schema: fact_tickets + dim_priority, dim_category, dim_channel,
--         dim_assignment_group, dim_status
-- NOTE: dataset is synthetic sample data generated by generate_data.py.

-- 1. Overall SLA performance
SELECT COUNT(*) AS total_tickets,
       SUM(resolved_at IS NOT NULL) AS resolved,
       ROUND(100.0 * SUM(sla_breached) / SUM(resolved_at IS NOT NULL), 2)
           AS breach_pct,
       ROUND(100.0 * AVG(reopened_flag), 2) AS reopen_pct
FROM fact_tickets;

-- 2. Breach rate and average resolution by priority
SELECT p.priority, COUNT(*) AS tickets,
       ROUND(AVG(f.resolution_hours), 1) AS avg_resolution_hours,
       ROUND(100.0 * SUM(f.sla_breached) / SUM(f.resolved_at IS NOT NULL), 1)
           AS breach_pct
FROM fact_tickets f JOIN dim_priority p USING (priority_key)
GROUP BY p.priority ORDER BY p.priority;

-- 3. Category volume, breach rate, average resolution
SELECT c.category, COUNT(*) AS tickets,
       ROUND(100.0 * SUM(f.sla_breached) / SUM(f.resolved_at IS NOT NULL), 1)
           AS breach_pct,
       ROUND(AVG(f.resolution_hours), 1) AS avg_resolution_hours
FROM fact_tickets f JOIN dim_category c USING (category_key)
GROUP BY c.category ORDER BY tickets DESC;

-- 4. Breach rate by assignment group
SELECT g.assignment_group, COUNT(*) AS tickets,
       ROUND(100.0 * SUM(f.sla_breached) / SUM(f.resolved_at IS NOT NULL), 1)
           AS breach_pct
FROM fact_tickets f
JOIN dim_assignment_group g USING (assignment_group_key)
GROUP BY g.assignment_group ORDER BY breach_pct DESC;

-- 5. Open backlog aging (age at snapshot = day after last created ticket)
SELECT CASE WHEN age_days <= 3 THEN '0-3 days'
            WHEN age_days <= 7 THEN '4-7 days'
            WHEN age_days <= 14 THEN '8-14 days'
            ELSE '15+ days' END AS age_bucket,
       COUNT(*) AS open_tickets
FROM fact_tickets WHERE resolved_at IS NULL
GROUP BY age_bucket;

-- 6. Weekend effect on resolution time
SELECT CASE WHEN strftime('%w', created_at) IN ('0', '5', '6')
            THEN 'Fri-Sun' ELSE 'Mon-Thu' END AS period,
       ROUND(AVG(resolution_hours), 1) AS avg_resolution_hours
FROM fact_tickets WHERE resolved_at IS NOT NULL GROUP BY period;
